function openRescue() {
  /* bug7002/bug7035：把当前所选物业管理区域与预警事件透传到求援工单页，
   * 使提交后返回巡检页（尤其 navigateBack 失败走 redirectTo 兜底时）仍能锁定并回填区域与事件 */
  const parts: string[] = []
  if (complexId.value) parts.push(`complexId=${encodeURIComponent(complexId.value)}`)
  if (complexName.value) parts.push(`complexName=${encodeURIComponent(complexName.value)}`)
  if (eventId.value) parts.push(`eventId=${encodeURIComponent(eventId.value)}`)
  if (stageSelection.value?.eventName) parts.push(`eventName=${encodeURIComponent(stageSelection.value.eventName)}`)
  uni.navigateTo({ url: `/pages/rescue/index${parts.length ? '?' + parts.join('&') : ''}` })
}

