import { expect, test } from '@playwright/test'

/**
 * bug7035：求援工单提交成功后返回汛中巡检页，必须保留物业区域与预警事件。
 * 采用 page.route mock 提交链路（save/submit/detail），无登录依赖；
 * 从带参 URL 直达 rescue 页，提交后断言 redirectTo 的目标 hash 含全参且编码正确、区域回填显示。
 */
test.describe('求援提交后返回巡检页保留区域与事件 (bug7035)', () => {
  const COMPLEX_ID = 'C-7035'
  const COMPLEX_NAME = '嘉越时代花园'
  const EVENT_ID = 'E-7035'
  const EVENT_NAME = '暴雨&内涝' // 含特殊字符，验证 encodeURIComponent

  function rescueUrl(extra = '') {
    const q = [
      `complexId=${encodeURIComponent(COMPLEX_ID)}`,
      `complexName=${encodeURIComponent(COMPLEX_NAME)}`,
      `eventId=${encodeURIComponent(EVENT_ID)}`,
      `eventName=${encodeURIComponent(EVENT_NAME)}`,
    ].join('&')
    return `#/pages/rescue/index?${q}${extra}`
  }

  async function mockSubmit(page: import('@playwright/test').Page) {
    await page.route('**/v2.0/safety/flood/rescue/save**', async route => {
      await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ code: 200, data: 7035 }) })
    })
    await page.route('**/v2.0/safety/flood/rescue/submit**', async route => {
      await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ code: 200, data: null }) })
    })
    await page.route('**/v2.0/safety/flood/rescue/7035**', async route => {
      await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({
        code: 200,
        data: { rescueId: 7035, rescueNo: 'QYGD20261127000001', status: '1', contactName: '测试', contactPhone: '13968741214', urgentLevel: '2', dangerDesc: '测试险情', supportDesc: '测试支援', createTime: '2026-11-27 08:00:00', logs: [] },
      }) })
    })
    // 物业区域搜索接口：固定返回测试小区，避免依赖外部数据
    await page.route('**/v2.0/safety/**/complex**', async route => {
      await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ code: 200, data: { records: [{ code: COMPLEX_ID, name: COMPLEX_NAME }], total: 1 } }) })
    })
  }

  async function fillAndSubmit(page: import('@playwright/test').Page) {
    // 无登录态，联系人/电话/描述需手动填（submitRescueRemote 校验必填）
    await page.locator('input[aria-label="联系人"]').fill('测试')
    await page.locator('input[aria-label="联系电话"]').fill('13968741214')
    await page.locator('textarea[aria-label="现场险情描述"]').fill('汛中险情测试')
    await page.locator('textarea[aria-label="所需支援描述"]').fill('需要支援测试')
    await page.locator('.action-button', { hasText: '提 交' }).click()
  }

  test('提交后 redirectTo 保留 kind=mid 与全参（含编码）且区域回填', async ({ page }) => {
    await mockSubmit(page)
    await page.goto('/')
    await page.evaluate(hash => { location.hash = hash }, rescueUrl())
    await expect(page.locator('input[aria-label="物业管理区域"]')).toHaveValue(COMPLEX_NAME, { timeout: 30_000 })
    await fillAndSubmit(page)
    // 兜底路径：redirectTo 到带全参的巡检页；hash 含 kind=mid 与编码后的各参数
    await expect(page).toHaveURL(new RegExp(`kind=mid.*complexId=${COMPLEX_ID}`, 's'), { timeout: 30_000 })
    const url = page.url()
    expect(url).toContain(`complexId=${COMPLEX_ID}`)
    expect(url).toContain(`complexName=${encodeURIComponent(COMPLEX_NAME)}`)
    expect(url).toContain(`eventId=${EVENT_ID}`)
    expect(url).toContain(`eventName=${encodeURIComponent(EVENT_NAME)}`)
  })

  test('eventName 含 & 不串参：各参数边界完整', async ({ page }) => {
    await mockSubmit(page)
    await page.goto('/')
    await page.evaluate(hash => { location.hash = hash }, rescueUrl())
    await expect(page.locator('input[aria-label="物业管理区域"]')).toHaveValue(COMPLEX_NAME, { timeout: 30_000 })
    await fillAndSubmit(page)
    await expect(page).toHaveURL(/kind=mid/, { timeout: 30_000 })
    const url = page.url()
    const params = new URLSearchParams(url.split('?')[1] || '')
    expect(params.get('complexId')).toBe(COMPLEX_ID)
    expect(params.get('complexName')).toBe(COMPLEX_NAME)
    expect(params.get('eventId')).toBe(EVENT_ID)
    expect(params.get('eventName')).toBe(EVENT_NAME)
  })

  test('eventId/eventName 缺失时兜底 URL 不串参，仅带 kind 与区域', async ({ page }) => {
    await mockSubmit(page)
    await page.goto('/')
    await page.evaluate(() => {
      location.hash = `#/pages/rescue/index?complexId=${encodeURIComponent('C-7035')}&complexName=${encodeURIComponent('嘉越时代花园')}`
    })
    await expect(page.locator('input[aria-label="物业管理区域"]')).toHaveValue(COMPLEX_NAME, { timeout: 30_000 })
    await fillAndSubmit(page)
    await expect(page).toHaveURL(/kind=mid/, { timeout: 30_000 })
    const params = new URLSearchParams(page.url().split('?')[1] || '')
    expect(params.get('complexId')).toBe(COMPLEX_ID)
    expect(params.has('eventId')).toBe(false)
    expect(params.has('eventName')).toBe(false)
  })
})
